let mut raw=BTreeMap::new();let mut profile_rows=vec![];for(name,p)in a["profiles"].as_object().unwrap(){assert_eq!(p["PIDs"].as_array().unwrap().len(),1);assert_eq!(p["zero_lost"],true);assert_eq!(filehash(r(format!("perf/{name}.data"))),p["raw_sha256"].as_str().unwrap());raw.insert(name,p["raw_sha256"].clone());let total=p["symbol_periods"].as_object().unwrap().values().map(|v|v.as_u64().unwrap()).sum::<u64>();let mut top=p["symbol_periods"].as_object().unwrap().iter().map(|(k,v)|json!({"symbol":k,"period":v,"share":v.as_u64().unwrap()as f64/total as f64})).collect::<Vec<_>>();top.sort_by(|a,b|b["period"].as_u64().unwrap().cmp(&a["period"].as_u64().unwrap()));top.truncate(10);profile_rows.push(json!({"name":name,"samples":p["samples"],"top10":top}));}save(d.join("raw-profile-sha256.json"),&json!(raw));save(d.join("profile-review.json"),&json!(profile_rows));
